INSERT INTO exp_listings_publishers (id, name, kind, publishes_to, ops_notes, subtitle, display_sort, channel_role, role_status, auth_model, write_path, read_path, sandbox, notes) VALUES
('data_axle', 'Data Axle', 'aggregator', 'Major search engines · Internet Yellow Pages · In-car navigation systems · Smart speakers / virtual assistants · Mobile apps · Directory assistance (411) · AI-driven search surfaces', '["Verification is human: automated match → teleresearch (3 calls / 3 business days) → manual research. Unverifiable = failed.","Monthly resubmission recommended — recency is passed to publishers as a quality signal.","3 failed submissions = 90-day limbo. Duplicates removed via Account Executive.","Renewal emails at 30–60 days out; A and R are the billable events."]'::jsonb, 'Local Listings Premium · aggregator · API v1', 10, 'distribution', 'proposed', 'Local Listings Premium account (API v1)', 'Local Listings Premium API v1 submissions (A/U/R/D)', NULL, NULL, 'A and R are billable; 3 failed submissions = 90-day limbo; verification is human teleresearch.'),
('google', 'Google Business Profile', 'direct', 'Google Search · Google Maps · AI Overviews / Gemini surfaces · the primary local discovery surface', '["Access: enable in GCP Console + request GBP API access (quota starts at 0 until approved) — self-serve application, not a partner agreement.","updateMask required on every patch; categories and phone numbers update as whole objects, never partially.","attributes.list?show_all per category+region = the per-category field oracle; attributes change without API versioning — Curator watch-item.","getGoogleUpdated diffs = drift detection: Google and users can edit listings; masks show exactly which fields moved.","Google may auto-add services to service lists — monitor and prune incorrect ones (permanent fix per Google)."]'::jsonb, 'direct · Business Info v1 + v4 + Food Menus + Lodging + Place Actions', 20, 'direct', 'proposed', 'OAuth 2.0 via GCP project + GBP API access request (quota 0 until approved; self-serve application)', 'Business Information API v1 PATCH with updateMask (+ v4 Media/Posts/Q&A/Reviews, Food Menus, Lodging, Place Actions)', 'Business Information API get + getGoogleUpdated (drift diff)', NULL, 'Categories and phone numbers update as whole objects.'),
('foursquare', 'Foursquare', 'aggregator', 'Apple Maps · OpenAI · Uber · Nextdoor · Yahoo! Japan · navigation & AI-search surfaces via FSQ OS Places', '["Three write paths: Place Match (read/harmonize, self-serve key) · Feedback API propose-edits (Service Account key, reviewed proposals, status endpoint) · Business Listings bulk authoritative publishing (partner agreement — in motion).","Legacy V3 endpoints deprecated May 15, 2026 — integrate against the new FSQ OS Places-powered endpoints only.","Feedback proposals are reviewed by Foursquare before applying; Get Feedback Status closes the loop.","FSQ Places powers Apple Maps and OpenAI — the most AI-citation-relevant aggregator on the list."]'::jsonb, 'FSQ OS Places · aggregator · Places + Feedback APIs', 30, 'distribution', 'proposed', 'Self-serve key (Place Match); Service Account key (Feedback API); partner agreement (bulk publishing)', 'Feedback API propose-edits (reviewed); Business Listings bulk authoritative publishing (partner agreement in motion)', 'Place Match + Get Feedback Status', NULL, 'Legacy V3 endpoints deprecated 2026-05-15 — FSQ OS Places endpoints only.'),
('meta', 'Facebook / Instagram (Meta)', 'channel', 'Facebook Pages · Instagram · Meta search surfaces · WhatsApp Business linkage', '["Identity + content channel, not a listings feed: page/profile fields sync where writable, drift-audit where not (category, IG bio).","Graph API v25.0 current; versions sunset ~2 years — pin and bump ahead of expiry.","IG prerequisites compound onboarding: professional account + linked FB Page (business path) + PPA where required.","FIELD-WRITABILITY VERIFICATION PENDING: Meta''s Page reference is JS-walled to automated readers — final per-field write truth comes from Graph Explorer (metadata=1) + sandbox POSTs on a test page during App Review setup. Rows marked pipeline are the known-restricted set."]'::jsonb, 'identity + content channel · Graph API v25', 40, 'direct', 'proposed', 'OAuth page tokens (60-day long-lived, refresh ~50 days) + App Review per permission', 'Graph API v25 Page fields where writable + FB/IG publishing', 'Graph API (metadata=1) for field-writability and drift audit', 'Test page via Graph Explorer + sandbox POSTs during App Review setup', 'Field writability pending verification; page name and category are drift-audit only.'),
('linkedin', 'LinkedIn', 'channel', 'LinkedIn feed · organization pages · member networks · LinkedIn search', '["Primarily a professional-lane CONTENT channel: member-voice posting is the value; org listing fields are thin and mostly UI-managed.","No native post scheduling — platform scheduler owns timing."]'::jsonb, 'professional content channel · Community Management API', 50, 'candidate', 'proposed', 'OAuth via LinkedIn Developer Program review (Community Management API)', 'Member + organization posts (w_member_social); org fields largely UI-managed', NULL, NULL, 'Content channel; no native post scheduling.'),
('apple', 'Apple Business', 'direct', 'Apple Maps · Siri · Spotlight · Safari · Wallet — the default iPhone discovery surface', '["Two write paths: self-serve dashboard (available today, per-location) and Location API at scale (partner agreement — joins the DA/FSQ agreement track).","Apple ALSO ingests Foursquare data — our FSQ rail reaches Apple Maps passively; a claimed Apple Business listing is the authoritative override.","Showcase mechanics (3-day approval, 30-day expiry) are scheduler constraints for the offers pipeline."]'::jsonb, 'direct · place cards · dashboard now, Location API partner-gated', 60, 'direct', 'proposed', 'Self-serve Apple Business dashboard; Location API requires a partner agreement + Partner ID', 'Dashboard per location today; Location API at scale via listing-management partners', NULL, NULL, 'Also ingests Foursquare data passively; a claimed listing is the authoritative override.'),
('bing', 'Bing Places (Microsoft)', 'direct', 'Bing Search + Maps · Copilot · ChatGPT web search · Yahoo · AOL · DuckDuckGo · Windows/Edge · voice (Cortana, Alexa)', '["The second AI-citation pipe: Bing''s index feeds Microsoft Copilot and ChatGPT''s local answers — a claimed, complete listing is how AI assistants describe the business correctly.","Strategic rail: Google→Bing auto-sync means our Google publishing propagates here nearly free; the runtime''s job is post-sync auditing (especially categories) rather than duplicate submission.","One-way sync only (Google→Bing); Bing-specific fields (Deals) are managed directly."]'::jsonb, 'direct · bing.com/forbusiness · Google auto-sync rail', 70, 'direct', 'proposed', 'No public self-serve listings API; enterprise API via partner/agency track', 'Google→Bing import + periodic auto-sync; bulk Excel upload; dashboard for Bing-only fields (Deals)', NULL, NULL, 'Runtime job is post-sync auditing (especially categories), not duplicate submission.'),
('tomtom', 'TomTom', 'rail_fed', 'In-car navigation (OEM embeds) · TomTom GO/AmiGO apps · Azure Maps + Bing Maps (Microsoft partnership) · Yellow Pages Canada · apps built on TomTom APIs · ~800M users claimed', '["Rail-fed publisher: this card documents a DESTINATION our DA + FSQ rails already reach, not a new integration to build.","MapShare edits are review-team moderated with slow device propagation — corrections channel, not a publishing channel.","Runtime job here is verification: confirm the profile appears correctly via TomTom Search API (self-serve developer key, read-only) and file MapShare corrections on drift."]'::jsonb, 'rail-fed · global POI database · reached via DA + FSQ', 80, 'candidate', 'proposed', 'Self-serve developer key (read-only); no public listings write API', 'DA + FSQ rails; MapShare corrections (moderated, slow)', 'TomTom Search API', NULL, 'Rail-fed destination, not a new integration.'),
('yelp', 'Yelp', 'trust_anchor', 'Yelp Search + app · Apple Maps (reviews/photos historically) · Amazon Alexa local answers · voice assistants', '["Write access at scale is a partnership (Yelp Knowledge / licensing) — joins the DA/FSQ/Apple agreement track.","Fusion API (self-serve key) is the verification rail: confirm listing state, ingest rating/count as reputation signals.","The review-solicitation prohibition is a hard compliance boundary for the campaigns product."]'::jsonb, 'trust anchor · claim + dashboard · partner track for scale', 90, 'candidate', 'proposed', 'Self-serve Fusion API key (read); write at scale via Yelp Knowledge / licensing partnership', 'Claim + dashboard; partner track for scale', 'Fusion API (rating, count, 3 excerpts)', NULL, 'Review solicitation prohibited — excluded from campaign solicitation flows.'),
('here', 'HERE', 'rail_fed', 'Amazon Alexa · embedded auto navigation (BMW, Mercedes, Audi consortium + many OEMs) · Garmin · enterprise/logistics platforms built on HERE APIs', '["Rail-fed destination: reached through the aggregator layer, not direct integration; runtime job = verify via HERE Geocoding & Search API (self-serve read key) + Map Creator corrections on drift.","Strategic weight: HERE feeds Alexa and most European in-car navigation — the voice + automotive surface."]'::jsonb, 'rail-fed · voice + automotive surface', 100, 'distribution', 'proposed', 'Self-serve read key (Geocoding & Search API); no public listings write API', 'Aggregator rails (licensed suppliers) + Map Creator corrections', 'HERE Geocoding & Search API', NULL, 'Rail-fed: feeds Alexa and most European in-car navigation.'),
('localeze', 'Localeze (TransUnion)', 'aggregator', '80–90+ authorized platforms: Google · Apple Maps · Bing · Yahoo · TomTom · YP.com · navigation systems · voice assistants (Alexa rail) · mobile apps', '["Contract-gated at scale (enterprise bulk) — joins the agreement track; SMB self-serve exists for early testing.","Overlap management is the real work: DA + FSQ + Localeze + our direct writes all touch Google/Apple/Bing/TomTom — the runtime needs a source-priority matrix so rails reinforce rather than fight."]'::jsonb, 'aggregator · 80–90+ platform network · contract-gated at scale', 110, 'distribution', 'proposed', 'SMB self-serve; enterprise bulk via contract with account manager', 'Enterprise bulk add/edit/release/close (contract)', NULL, 'SMB self-serve tier for early testing', 'Needs a source-priority matrix with DA + FSQ + our direct writes.'),
('nextdoor', 'Nextdoor', 'channel', 'Nextdoor neighborhoods · local recommendation threads · the highest-trust local surface per household', '["Claim is self-serve and free; FSQ rail supplies the POI baseline — claiming converts it to an owned trust surface.","Recommendations are organic-only: reputation here is earned, which is exactly why it signals."]'::jsonb, 'neighborhood trust surface · claim self-serve · FSQ-seeded', 120, 'candidate', 'proposed', 'Free self-serve claim at business.nextdoor.com', 'Dashboard-first; scale via partner/aggregator syndication', NULL, NULL, 'FSQ rail supplies the POI baseline.')
INSERT INTO exp_listings_field_map (publisher_id, section, section_note, their_field, our_target, rules, applicability, status_default, variant_family, sort, catalog_version, required, api_field_path, rule_spec) VALUES
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Submission Type', 'Pipeline state (A/U/R/D)', 'A=Add (billable) · U=Update (free <12mo) · R=Renew (billable, 12mo+) · D=Delete (out of business only). They auto-detect type from history.', 'base', 'pipeline', NULL, 1, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Company Name', 'Registry: DBA Name [identity]', 'DBA, not legal name. No location suffixes (“Best Buy - Omaha” fails). Pipes or characters around ampersands fail up-front validation.', 'base', 'mapped', NULL, 2, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Location Address', 'Registry: Street Address [location]', 'Address only, no cross-street text. USPS-standardized suffixes (St, Ave, NW). Canadian suites: “99-894 Road”, suite attribute left blank.', 'base', 'mapped', NULL, 3, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Location City', 'Profile: address.addressLocality', 'City of physical location.', 'base', 'mapped', NULL, 4, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Location State/Province', 'Profile: address.addressRegion', 'Abbreviated, not spelled out. US + DC + GU/PR/VI only.', 'base', 'mapped', NULL, 5, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Location Zip/Postal Code', 'Profile: address.postalCode', '5 digits, leading zero preserved.', 'base', 'mapped', NULL, 6, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Location Phone', 'Registry: Phone Number [presence]', 'LOCAL number required, 10-digit; toll-free alone is rejected. Their primary match key — wrong phone creates duplicates.', 'base', 'mapped', NULL, 7, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Core Required', 'Their publishing minimum — failures here fail the whole submission.', 'Primary SIC', 'gcid → SIC crosswalk (to build)', 'Their category taxonomy. Mexican Restaurant ≈ 581208. Professional credentials must correspond to SIC (ATTY ↔ 811103).', 'base', 'missing_ours', NULL, 8, 'listings_tab_2026_07', true, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Operating Hours', 'Registry: Operating Hours [services]', 'Multi-range per day supported; format per template tab 3. “By appointment” NOT accepted.', 'base', 'mapped', 'hours', 9, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Cuisine', 'Registry: Cuisine Type [identity]', 'Fixed enum (their published cuisine list). Value must match exactly.', 'base', 'mapped', NULL, 10, 'listings_tab_2026_07', NULL, 'Cuisine', NULL),
