('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Web Address', 'Profile: location page URL', 'Longer, location-specific page.', 'base', 'mapped', NULL, 13, 'listings_tab_2026_07', NULL, NULL, NULL),
