('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Brands / Products / Services', 'Registry: brands + services nodes', 'e.g. brands carried; ATM special rule — bank name goes in Brands.', 'base', 'mapped', 'brand', 15, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Business Description', 'Registry: Description [identity]', 'Verified by their research team.', 'base', 'mapped', NULL, 16, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Alternative Name', 'Registry: alternate-name node', 'e.g. “Starbucks Pike Street”.', 'base', 'missing_ours', 'alt_name', 17, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Anchor/Host Business', 'Registry: anchor/host node', '“Starbucks inside Target” — Target is anchor/host.', 'base', 'missing_ours', 'anchor_host', 18, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Toll Free / Fax', 'Registry: Toll-Free Number + Fax Number [presence]', 'Fax + attorney SIC 811103 triggers a warning (category-conditional rule).', 'base', 'mapped', NULL, 19, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Enhanced Content', 'Their “highly used by publishers” list — richer listings rank and retain better.', 'Extended attributes (accessibility, parking, amenities — 400+ read-side)', 'Registry: operational layer nodes', 'Writable subset lives in the login-gated template (attributes change through the year) — reconcile on template pull; operational nodes stand ready.', 'base', 'pipeline', NULL, 20, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Restaurant Attributes', 'Category-variant pack (their newest additions).', 'Takeout / Dining Options', 'Registry: Dine-In Offer, Online Ordering URL, Takeout nodes [services]', 'New attributes per their docs banner; submit via updated template.', 'restaurant_attributes', 'mapped', NULL, 21, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Restaurant Attributes', 'Category-variant pack (their newest additions).', 'Reservations', 'Registry: OpenTable Reservation Profile [presence]', '—', 'restaurant_attributes', 'mapped', NULL, 22, 'listings_tab_2026_07', NULL, 'Reservations', NULL),
