('data_axle', 'Images (×5)', NULL, 'Primary Image + Image 2–5', 'Registry: Logo [identity], Photo Gallery nodes [content]', 'URL of the image itself (not the page). jpg/png/non-animated gif. ≥1600px wide recommended. Primary = storefront with visible sign. Human-reviewed; duplicates rejected. Images accumulate across submissions.', 'base', 'mapped', NULL, 24, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Is Professional Record?', 'entity_type (professional lane)', 'Y/N; defaults N.', 'professional_records', 'na', NULL, 25, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Professional First/Last Name', 'Profile: person givenName/familyName', 'Alpha + apostrophes only.', 'professional_records', 'na', NULL, 26, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Professional Firm Name', 'Profile: worksFor organization', 'Hospital, company, or office.', 'professional_records', 'na', NULL, 27, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Professional Credentials', 'Registry: authority-ring credential nodes', 'Fixed enum; MUST correspond to Primary SIC (ATTY ↔ 811103). Insurance agents: carrier-specific name formats (“John Smith State Farm Insurance Agent”).', 'professional_records', 'na', NULL, 28, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Professional Standardized Title', 'Profile: jobTitle', 'Enum: CEO, Owner, President, EVP, SVP, VP, Plant Manager, Office Manager.', 'professional_records', 'na', NULL, 29, 'listings_tab_2026_07', NULL, NULL, NULL),
('data_axle', 'Professional Records', 'Their schema splits professional vs location exactly where our entity model does. This category is a location — block not applicable here; required for professional categories.', 'Professional Email', 'Profile: email', 'Not available for Canadian records.', 'professional_records', 'na', NULL, 30, 'listings_tab_2026_07', NULL, NULL, NULL),
('google', 'Identity & Categories', 'Business Information API v1 · locations resource. Our crosswalk is IDENTITY: platform gcids are GBP category IDs.', 'title', 'Registry: DBA Name [identity]', 'Real-world name only. FORBIDDEN in name: taglines, store codes, special chars, hours/open status, phone, URLs, service info, address, containment (“Chase ATM in Duane Reade”). Violations risk suspension.', 'base', 'mapped', NULL, 1, 'listings_tab_2026_07', NULL, 'title', NULL),
('google', 'Identity & Categories', 'Business Information API v1 · locations resource. Our crosswalk is IDENTITY: platform gcids are GBP category IDs.', 'categories.primaryCategory', 'Profile: primary gcid — native', 'Must be a valid GBP category ID. Ours ARE GBP category IDs — identity mapping, verified by construction.', 'base', 'mapped', NULL, 2, 'listings_tab_2026_07', NULL, 'categories.primaryCategory', NULL),
('google', 'Identity & Categories', 'Business Information API v1 · locations resource. Our crosswalk is IDENTITY: platform gcids are GBP category IDs.', 'categories.additionalCategories (≤9)', 'Profile: composed categories 2–10', 'Up to 9 additional — exactly our composition contract (primary + 9). Primary + additional must be updated together (no partial mask).', 'base', 'mapped', NULL, 3, 'listings_tab_2026_07', NULL, NULL, NULL),
('google', 'Identity & Categories', 'Business Information API v1 · locations resource. Our crosswalk is IDENTITY: platform gcids are GBP category IDs.', 'storeCode', 'Profile: external location code', 'Multi-location dedupe key for bulk management.', 'base', 'mapped', NULL, 4, 'listings_tab_2026_07', NULL, 'storeCode', NULL),
